import os
import time
from datetime import datetime

from hran_pacman.bases.logger import LOGGER
from hran_pacman.exceptions import FileLocked
from hran_pacman.storages_bases import PERMISSION_LEVEL

try:
    import thread
except ImportError:  # pragma: no cover
    import _thread as thread


class DyingFile(object):
    """**File + Timestamp based lockfile implementation**

    DyingFile allows for queuing multiple instances of executors.
    Each executor can become "provider" or "customer".

    There can be only one provider, it's always first executor
    that locks "task". Lock tells rest of executors to become customers.

    When task is already locked (lock file is created) and
    lock is "alive" (timestamp is not deprecated), executor
    becomes a "customer", passive worker that waits for
    result of another "provider" executor.

    Customers are constantly checking for results of task,
    every time if lock is still "fresh", if not, they will assume that
    task is done and you can get results.

    """

    def __init__(self, file_path, timeout=180, update_time=15):
        self.file_path = file_path
        self.timeout = timeout
        self.update_time = update_time
        self.stop_status = False

    def _loop_over_file(self, msg):
        try:
            if not os.path.exists(self.file_path):
                while not self.stop_status:
                    self.ensure_that_existing_file_is_accessible()
                    self.update_file()
                    time.sleep(self.update_time)
            else:
                raise FileLocked
        except Exception:
            LOGGER.exception("Unexpected exception occurred")

    def ensure_that_existing_file_is_accessible(self):
        if os.path.exists(self.file_path):
            os.chmod(self.file_path, PERMISSION_LEVEL)

    def update_file(self):
        with open(self.file_path, "w") as dying_file:
            status = str(datetime.utcnow())
            dying_file.write(status)

    def acquire(self, msg):
        """**[Provider]** Try to acquire lock.

        Loop over and over waiting for lock
        to be free (removed or deprecated).

        """
        LOGGER.info(msg)
        thread.start_new(self._loop_over_file, (msg,))

    def unlock(self):
        """**[Provider]** Remove lock (delete file)
        and by this, inform rest of executors (customers)
        that you have done your job as provider.

        """
        self.stop_status = True
        if os.path.exists(self.file_path):
            os.remove(self.file_path)

    def check(self, attempting_frequency=15):
        """**[Provider/Customer]** Check if task isn't already locked.

        If task is locked, become "customer"
        by waiting with constantly checking

        if lock is "alive" which means that
        another executor ("provider") is still working on it.

        End with assumption that task was done
        and you can expect correct results.
        """
        if not os.path.exists(self.file_path):
            return True
        else:
            counter = 0
            while True:
                counter += 1
                try:
                    current_time = self.get_actual_time()
                    delta = self.get_time_delta(current_time)
                except IOError:
                    return True
                if delta > self.timeout:
                    os.remove(self.file_path)
                    return True
                else:
                    time.sleep(attempting_frequency)
                    LOGGER.info(
                        "Someone else downloading this file.\n"
                        + "Wait to finish and program will download\n"
                        + "it faster from remote.\n"
                        + "| Attempt No. "
                        + str(counter)
                        + " |\n| Total time from start: "
                        + str(counter * attempting_frequency)
                        + "sec |"
                    )

    def get_actual_time(self):
        """Extract timestamp from lock file and return it as datetime obj.

        In case of empty file, return "oldest possible date" which will
        always mean that lock file is expired and must be replaced.
        """
        with open(self.file_path, "r") as dying_file:
            raw_time = dying_file.read()
            if not raw_time:
                return datetime.fromtimestamp(0)
            return self.convert_time(raw_time)

    def convert_time(self, time_text):
        try:
            return datetime.strptime(time_text, "%Y-%m-%d %H:%M:%S.%f")
        except ValueError:
            return datetime.strptime(time_text, "%Y-%m-%d %H:%M:%S")

    def get_time_delta(self, time_to_compare):
        return (datetime.utcnow() - time_to_compare).total_seconds()
